# A stretch stays walkable when it is made shorter, so the answer can be found by binary
# search on the length. For a fixed length the window maxima come from the block trick
# (prefix maxima inside each block of that length, suffix maxima likewise), not a deque.
import sys

def feasible(length, c, pre, budget, n):
    pref = [0] * n
    suff = [0] * n
    for i in range(n):
        pref[i] = c[i] if i % length == 0 else (pref[i - 1] if pref[i - 1] > c[i] else c[i])
    for i in range(n - 1, -1, -1):
        if i % length == length - 1 or i == n - 1:
            suff[i] = c[i]
        else:
            suff[i] = suff[i + 1] if suff[i + 1] > c[i] else c[i]
    for i in range(0, n - length + 1):
        j = i + length - 1
        top = suff[i] if suff[i] > pref[j] else pref[j]
        if pre[j + 1] - pre[i] - top <= budget:
            return True
    return False

data = sys.stdin.read().split()
n = int(data[0])
budget = int(data[1])
c = [int(x) for x in data[2:2 + n]]
pre = [0] * (n + 1)
for i in range(n):
    pre[i + 1] = pre[i] + c[i]
lo, hi = 1, n
while lo < hi:
    mid = (lo + hi + 1) // 2
    if feasible(mid, c, pre, budget, n):
        lo = mid
    else:
        hi = mid - 1
print(lo)
